// utils/proxy/{proxy}/interfaces.ts

// Interface commune — service réel et proxy l'implémentent identiquement
export interface {Proxy}Service {
  list(page?: number):                       Promise<unknown[]>
  get(id: number):                           Promise<unknown>
  create(payload: unknown):                  Promise<unknown>
  update(id: number, payload: unknown):      Promise<unknown>
  remove(id: number):                        Promise<void>
  // Ajoute ici les méthodes spécifiques
}

// Rôles autorisés dans le projet
export type UserRole = 'admin' | 'editor' | 'reader'

// Configuration des permissions par opération
export interface PermissionConfig {
  list:   UserRole[]
  get:    UserRole[]
  create: UserRole[]
  update: UserRole[]
  remove: UserRole[]
}

// utils/proxy/{proxy}/{Proxy}Proxies.ts
import type { {Proxy}Service, PermissionConfig, UserRole } from './interfaces'

// ── Proxy de protection — contrôle d'accès par rôle ──────────────────
export class {Proxy}ProtectedProxy implements {Proxy}Service {
  constructor(
    private readonly service:     {Proxy}Service,
    private readonly permissions: PermissionConfig,
    private readonly getRole:     () => UserRole | null
  ) {}

  private checkPermission(operation: keyof PermissionConfig): void {
    const role = this.getRole()
    if (!role || !this.permissions[operation].includes(role)) {
      throw new Error(
        `[{Proxy}Proxy] Accès refusé : opération "${operation}" non autorisée pour le rôle "${role}"`
      )
    }
  }

  list(page = 1)                      { this.checkPermission('list');   return this.service.list(page) }
  get(id: number)                     { this.checkPermission('get');    return this.service.get(id) }
  create(payload: unknown)            { this.checkPermission('create'); return this.service.create(payload) }
  update(id: number, p: unknown)      { this.checkPermission('update'); return this.service.update(id, p) }
  remove(id: number)                  { this.checkPermission('remove'); return this.service.remove(id) }
}

// ── Proxy de lazy loading — initialise le service au premier accès ────
export class {Proxy}LazyProxy implements {Proxy}Service {
  private instance: {Proxy}Service | null = null

  constructor(private readonly factory: () => {Proxy}Service) {}

  private get(): {Proxy}Service {
    if (!this.instance) {
      this.instance = this.factory()
    }
    return this.instance
  }

  list(page = 1)                 { return this.get().list(page) }
  get(id: number)                { return this.get().get(id) }
  create(payload: unknown)       { return this.get().create(payload) }
  update(id: number, p: unknown) { return this.get().update(id, p) }
  remove(id: number)             { return this.get().remove(id) }
}

// Permissions par défaut — à personnaliser selon le domaine
export const {PROXY}_DEFAULT_PERMISSIONS: PermissionConfig = {
  list:   ['admin', 'editor', 'reader'],
  get:    ['admin', 'editor', 'reader'],
  create: ['admin', 'editor'],
  update: ['admin', 'editor'],
  remove: ['admin']
}

// composables/{proxy}/use{Proxy}Service.ts
import {
  {Proxy}ProtectedProxy,
  {PROXY}_DEFAULT_PERMISSIONS
} from '~/utils/proxy/{proxy}/{Proxy}Proxies'
import type { {Proxy}Service } from '~/utils/proxy/{proxy}/interfaces'

// Service de base — implémentation sans proxy
class {Proxy}BaseService implements {Proxy}Service {
  // Ajoute ici l'implémentation de base
  async list(page = 1)                  { return [] }
  async get(id: number)                 { return {} }
  async create(payload: unknown)        { return {} }
  async update(id: number, p: unknown)  { return {} }
  async remove(id: number)              { }
}

export const use{Proxy}Service = () => {
  const authStore = useAuthStore()

  // Le proxy contrôle l'accès selon le rôle — le client ne voit pas la différence
  const service = new {Proxy}ProtectedProxy(
    new {Proxy}BaseService(),
    {PROXY}_DEFAULT_PERMISSIONS,
    () => (authStore.user as any)?.role ?? null
  )

  return {
    list:   (page?: number)               => service.list(page),
    get:    (id: number)                  => service.get(id),
    create: (payload: unknown)            => service.create(payload),
    update: (id: number, p: unknown)      => service.update(id, p),
    remove: (id: number)                  => service.remove(id)
  }
}

// tests/utils/proxy/{proxy}/{Proxy}Proxies.spec.ts
import { describe, it, expect, vi, beforeEach } from 'vitest'
import {
  {Proxy}ProtectedProxy,
  {Proxy}LazyProxy,
  {PROXY}_DEFAULT_PERMISSIONS
} from '~/utils/proxy/{proxy}/{Proxy}Proxies'
import type { {Proxy}Service } from '~/utils/proxy/{proxy}/interfaces'

const mockService: {Proxy}Service = {
  list:   vi.fn().mockResolvedValue([]),
  get:    vi.fn().mockResolvedValue({}),
  create: vi.fn().mockResolvedValue({}),
  update: vi.fn().mockResolvedValue({}),
  remove: vi.fn().mockResolvedValue(undefined)
}

beforeEach(() => vi.clearAllMocks())

describe('{Proxy}ProtectedProxy', () => {

  it('admin peut effectuer toutes les opérations', async () => {
    const proxy = new {Proxy}ProtectedProxy(mockService, {PROXY}_DEFAULT_PERMISSIONS, () => 'admin')
    await expect(proxy.list()).resolves.toBeDefined()
    await expect(proxy.create({})).resolves.toBeDefined()
    await expect(proxy.remove(1)).resolves.toBeUndefined()
  })

  it('reader peut lire mais pas créer', async () => {
    const proxy = new {Proxy}ProtectedProxy(mockService, {PROXY}_DEFAULT_PERMISSIONS, () => 'reader')
    await expect(proxy.list()).resolves.toBeDefined()
    expect(() => proxy.create({})).toThrow('Accès refusé')
  })

  it('reader ne peut pas supprimer', () => {
    const proxy = new {Proxy}ProtectedProxy(mockService, {PROXY}_DEFAULT_PERMISSIONS, () => 'reader')
    expect(() => proxy.remove(1)).toThrow('Accès refusé')
  })

  it('rôle null est refusé pour toutes les opérations', () => {
    const proxy = new {Proxy}ProtectedProxy(mockService, {PROXY}_DEFAULT_PERMISSIONS, () => null)
    expect(() => proxy.list()).toThrow('Accès refusé')
  })

})

describe('{Proxy}LazyProxy', () => {

  it('n\'initialise pas le service avant le premier appel', () => {
    const factory = vi.fn().mockReturnValue(mockService)
    const proxy   = new {Proxy}LazyProxy(factory)
    expect(factory).not.toHaveBeenCalled()
  })

  it('initialise le service au premier appel', async () => {
    const factory = vi.fn().mockReturnValue(mockService)
    const proxy   = new {Proxy}LazyProxy(factory)
    await proxy.list()
    expect(factory).toHaveBeenCalledTimes(1)
  })

  it('n\'initialise qu\'une seule fois pour plusieurs appels', async () => {
    const factory = vi.fn().mockReturnValue(mockService)
    const proxy   = new {Proxy}LazyProxy(factory)
    await proxy.list()
    await proxy.list()
    expect(factory).toHaveBeenCalledTimes(1)
  })

})
